const state={clients:[],products:[],cart:[],selectedProduct:null,multiSelection:new Map(),activeVisit:null,orderStarted:false,editingOrder:null,offlineOrderMode:false};
const OFFLINE_DB='VoyPidiendoOffline',OFFLINE_VERSION=1;
function offlineEnabled(){const entry=Object.entries(tenantConfig?.funciones||{}).find(([key])=>key.toLowerCase()==='pedidosoffline');return entry?.[1]===true}
function offlineScope(){return `${location.hostname}|${currentUser()?.usuario||'anonimo'}`}
function openOfflineDb(){return new Promise((resolve,reject)=>{const request=indexedDB.open(OFFLINE_DB,OFFLINE_VERSION);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains('sync'))db.createObjectStore('sync');if(!db.objectStoreNames.contains('orders'))db.createObjectStore('orders',{keyPath:'id'})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function offlineGet(store,key){const db=await openOfflineDb();return new Promise((resolve,reject)=>{const request=db.transaction(store).objectStore(store).get(key);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function offlinePut(store,value,key){const db=await openOfflineDb();return new Promise((resolve,reject)=>{const objectStore=db.transaction(store,'readwrite').objectStore(store),request=key===undefined?objectStore.put(value):objectStore.put(value,key);request.onsuccess=()=>resolve();request.onerror=()=>reject(request.error)})}
async function offlineDelete(store,key){const db=await openOfflineDb();return new Promise((resolve,reject)=>{const request=db.transaction(store,'readwrite').objectStore(store).delete(key);request.onsuccess=()=>resolve();request.onerror=()=>reject(request.error)})}
async function pendingOrders(){const db=await openOfflineDb(),scope=offlineScope();return new Promise((resolve,reject)=>{const request=db.transaction('orders').objectStore('orders').getAll();request.onsuccess=()=>resolve((request.result||[]).filter(x=>x.scope===scope));request.onerror=()=>reject(request.error)})}
async function updatePendingIndicator(){if(!offlineEnabled())return;try{const count=(await pendingOrders()).length;$('syncButton').textContent=count?`Sincronizar (${count} pendiente${count===1?'':'s'})`:'Sincronizar'}catch{}}
function isNetworkError(error){return !navigator.onLine||error instanceof TypeError||/failed to fetch|network|conexión|conexion/i.test(error?.message||'')}
async function cacheSyncData(data){await offlinePut('sync',{...data,savedAt:new Date().toISOString()},offlineScope())}
async function loadCachedSyncData(){const data=await offlineGet('sync',offlineScope());if(!data)return false;state.clients=data.clientes||[];state.products=data.productos||[];renderZones();renderClients();renderProducts();$('status').textContent=`Sin conexión · datos guardados: ${state.clients.length} clientes y ${state.products.length} artículos.`;return true}
async function queueOfflineOrder(payload,clientName){const id=payload.idOrigenApp;await offlinePut('orders',{id,scope:offlineScope(),payload,clientName,createdAt:new Date().toISOString()});await updatePendingIndicator()}
async function syncPendingOrders(){if(!offlineEnabled()||!navigator.onLine)return 0;const orders=await pendingOrders();let sent=0;for(const order of orders){try{await apiRequest('/api/pedidos',{method:'POST',body:JSON.stringify(order.payload)});await offlineDelete('orders',order.id);sent++}catch(error){if(isNetworkError(error))break;throw new Error(`Pedido pendiente de ${order.clientName}: ${error.message}`)}}await updatePendingIndicator();return sent}
