function toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3500)}
function appMessage(message,confirmation=false){return new Promise(resolve=>{const dialog=$('appDialog'),cancel=$('appDialogCancel'),accept=$('appDialogAccept');$('appDialogMessage').textContent=message;cancel.hidden=!confirmation;let done=false;const finish=value=>{if(done)return;done=true;dialog.close();resolve(value)};cancel.onclick=()=>finish(false);accept.onclick=()=>finish(true);dialog.oncancel=e=>{e.preventDefault();finish(false)};dialog.showModal()})}
function token(){return localStorage.getItem('voypidiendo_token')||''}
function headers(){return {'Authorization':`Bearer ${token()}`,'Content-Type':'application/json'}}
function roleName(role){return ({A:'Administrador',V:'Vendedor',P:'Consulta Pedidos',S:'Consulta Ventas',Q:'Consultas completas'})[role]||role}
function currentUser(){return JSON.parse(localStorage.getItem('voypidiendo_usuario')||'null')}
function featureEnabled(name){const entry=Object.entries(tenantConfig?.funciones||{}).find(([key])=>key.toLowerCase()===name.toLowerCase());return entry?entry[1]!==false:true}
function applyTenantFeatures(){document.querySelectorAll('[data-feature]').forEach(element=>element.hidden=!featureEnabled(element.dataset.feature));$('showTracking').hidden=$('showTracking').hidden||!featureEnabled('Seguimiento');$('showClientLocations').hidden=!featureEnabled('UbicacionClientes');if(!featureEnabled('Frio'))$('cold').checked=false;if(!featureEnabled('CargaMultiple')){$('multipleLoad').checked=false;switchLoadMode()}}
function showSession(user){const role=user?.rol,admin=role==='A',seller=role==='V',consultant=['A','P','S','Q'].includes(role),orders=['A','P','Q'].includes(role),sales=['A','S','Q'].includes(role);$('loginPanel').hidden=!!user;$('sessionPanel').hidden=!user;$('clientLocations').hidden=true;$('clientManagement').hidden=true;$('adminMenu').hidden=!consultant;$('sellerOrder').hidden=!seller;$('adminUsers').hidden=true;$('adminTracking').hidden=true;$('adminOrders').hidden=true;$('adminDashboard').hidden=true;$('adminSalesDashboard').hidden=true;$('adminAnnualDashboard').hidden=true;$('showUsers').hidden=!admin;$('showClients').hidden=!admin;$('showClientManagement').hidden=!(admin||seller);$('showTracking').hidden=!orders;$('showOrders').hidden=!orders;$('showDashboard').hidden=!orders;$('showSalesDashboard').hidden=!sales;$('showAnnualDashboard').hidden=!sales;$('showAnnualMoneyDashboard').hidden=!sales;$('syncButton').hidden=!seller;$('sessionUser').textContent=user?`${user.nombre} · ${roleName(role)}`:'';applyTenantFeatures()}
function showAdmin(section){const user=currentUser(),seller=user?.rol==='V',consultant=['A','P','S','Q'].includes(user?.rol);$('adminMenu').hidden=!!section||!consultant;$('sellerOrder').hidden=!!section||!seller;$('clientManagement').hidden=section!=='clients';$('adminUsers').hidden=section!=='users';$('adminTracking').hidden=section!=='tracking';$('adminOrders').hidden=section!=='orders';$('adminDashboard').hidden=section!=='dashboard';$('adminSalesDashboard').hidden=section!=='salesDashboard';$('adminAnnualDashboard').hidden=section!=='annualDashboard';if(section==='clients')openManagedClients();if(section==='users')loadUsers();if(section==='tracking'){initTrackingDates();loadTrackingFilters();loadTracking()}if(section==='orders'){ordersPage=1;initOrdersDates();const sellerFilter=$('ordersSeller').closest('label'),zoneFilter=$('ordersZone').closest('label');sellerFilter.hidden=seller;zoneFilter.hidden=seller;$('ordersSeller').value='';$('ordersZone').value='';if(!seller){loadOrderZones();loadSellers()}loadOrders()}if(section==='dashboard'){loadDashboardZones();loadSellers();loadOrderDashboardFilters();loadDashboard()}if(section==='salesDashboard'){loadSalesDashboardZones();loadBillingFilters();loadSalesDashboard()}if(section==='annualDashboard'){loadAnnualDashboardZones();loadAnnualFilters();loadAnnualDashboard()}}
let busyQueries=0;
function queryBusy(active){busyQueries=Math.max(0,busyQueries+(active?1:-1));$('queryBusy').hidden=busyQueries===0}
async function apiRequest(url,options={}){const busy=url.startsWith('/api/dashboard');if(busy)queryBusy(true);try{const response=await fetch(url,{...options,headers:{...headers(),...(options.headers||{})}});let data=null;try{data=await response.json()}catch{}if(!response.ok)throw new Error(data?.mensaje||`HTTP ${response.status}`);return data}finally{if(busy)queryBusy(false)}}
async function loadAppTitle(edit=false){try{const data=await apiRequest('/api/configuracion/titulo');$('appTitle').textContent=data.titulo;$('appSubtitle').textContent=data.subtitulo;document.title=data.titulo;if(edit){$('settingsTitle').value=data.titulo;$('settingsSubtitle').value=data.subtitulo}}catch{}}
function setTenantBrand(config){const logo=$('tenantLogo'),heading=$('brandHeading'),source=config.logo?.trim()||'/icons/icon.svg',custom=source!=='/icons/icon.svg';heading.classList.toggle('custom-brand',custom);logo.alt=custom?config.nombre||config.titulo||'Logo de la empresa':'';logo.onerror=()=>{logo.onerror=null;logo.src='/icons/icon.svg';heading.classList.remove('custom-brand')};logo.src=source}
async function loadTenantConfig(){try{tenantConfig=await apiRequest('/api/configuracion/empresa');localStorage.setItem(`voypidiendo_tenant_${location.hostname}`,JSON.stringify(tenantConfig))}catch{try{tenantConfig=JSON.parse(localStorage.getItem(`voypidiendo_tenant_${location.hostname}`)||'null')}catch{tenantConfig=null}}if(tenantConfig){$('appTitle').textContent=tenantConfig.titulo;$('appSubtitle').textContent=tenantConfig.subtitulo;document.title=tenantConfig.titulo;setTenantBrand(tenantConfig);document.documentElement.style.setProperty('--vp-brand',tenantConfig.colorPrincipal);document.documentElement.style.setProperty('--vp-dark',tenantConfig.colorSecundario);document.querySelector('meta[name="theme-color"]')?.setAttribute('content',tenantConfig.colorPrincipal);applyTenantFeatures()}else await loadAppTitle()}
async function saveAppTitle(){const titulo=$('settingsTitle').value.trim(),subtitulo=$('settingsSubtitle').value.trim();if(!titulo||!subtitulo)return toast('Complete título y subtítulo.');try{await apiRequest('/api/configuracion/titulo',{method:'PUT',body:JSON.stringify({titulo,subtitulo})});await loadAppTitle(true);toast('Títulos actualizados.')}catch(e){toast(e.message)}}
async function loadUsers(){try{await loadAppTitle(true);const users=await apiRequest('/api/usuarios');$('usersList').innerHTML=users.map(x=>`<tr><td>${escapeHtml(x.usuario)}</td><td>${escapeHtml(x.nombre)}</td><td>${roleName(x.rol)}</td><td>${x.codVend??'—'}</td><td><span class="pill">${x.habilitado?'Habilitado':'Deshabilitado'}</span></td><td><button class="secondary user-toggle" data-id="${x.id}" data-enabled="${!x.habilitado}">${x.habilitado?'Deshabilitar':'Habilitar'}</button> <button class="secondary user-password" data-id="${x.id}">Cambiar clave</button></td></tr>`).join('');$('usersList').querySelectorAll('.user-toggle').forEach(b=>b.onclick=async()=>{try{await apiRequest(`/api/usuarios/${b.dataset.id}/habilitado/${b.dataset.enabled}`,{method:'PUT'});await loadUsers()}catch(e){toast(e.message)}});$('usersList').querySelectorAll('.user-password').forEach(b=>b.onclick=async()=>{const clave=prompt('Nueva contraseña (mínimo 6 caracteres):');if(!clave)return;try{await apiRequest(`/api/usuarios/${b.dataset.id}/clave`,{method:'PUT',body:JSON.stringify({clave})});toast('Contraseña actualizada.')}catch(e){toast(e.message)}})}catch(e){toast(`Usuarios: ${e.message}`)}}
