async function searchDashboardClients(){const input=$('dashboardClient'),term=input.value.trim(),results=$('dashboardClientResults'),version=++dashboardClientSearchVersion;input.dataset.filter='';if(!term){dashboardClientMatches=[];results.className='product-results';results.innerHTML='';return}const query=new URLSearchParams({texto:term}),zone=$('dashboardZone').value;if(zone)query.set('zona',zone);try{const clients=await apiRequest(`/api/clientes/buscar?${query}`);if(version!==dashboardClientSearchVersion)return;dashboardClientMatches=clients;results.className='product-results visible';results.innerHTML=clients.length?clients.map((x,i)=>`<button class="product-result" data-index="${i}"><span class="code">#${x.codigo}</span><span>${escapeHtml(x.nombre)}</span><span>${escapeHtml(x.zona||'')}</span></button>`).join(''):'<div class="search-note">No se encontraron clientes.</div>';results.querySelectorAll('.product-result').forEach(button=>button.onclick=()=>selectDashboardClient(clients[Number(button.dataset.index)]))}catch(e){if(version===dashboardClientSearchVersion)toast(`Clientes: ${e.message}`)}}
