async function loadClientLocations(){if(typeof L==='undefined')return toast('No se pudo cargar el mapa.');if(!clientLocationsMap){clientLocationsMap=L.map('clientLocationsMap').setView([-34.6,-58.4],5);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(clientLocationsMap);clientLocationsLayer=L.layerGroup().addTo(clientLocationsMap);clientLocationsMap.on('click',e=>setClientLocationPin(e.latlng))}setTimeout(()=>clientLocationsMap.invalidateSize(),0);try{const clients=await apiRequest('/api/clientes/ubicaciones');clientLocationsLayer.clearLayers();const bounds=[];clients.forEach(x=>{const point=[Number(x.latitud),Number(x.longitud)];bounds.push(point);L.marker(point,{icon:L.divIcon({className:'client-map-marker',iconSize:[16,16]})}).bindPopup(`<strong>${x.codigo} - ${escapeHtml(x.nombre)}</strong><br>${escapeHtml(x.zona)||'Sin zona'}`).addTo(clientLocationsLayer)});if(bounds.length)clientLocationsMap.fitBounds(bounds,{padding:[35,35],maxZoom:16})}catch(e){toast(`Ubicaciones: ${e.message}`)}}
