function switchLoadMode(){const multiple=$('multipleLoad').checked;$('singleLoadPanel').hidden=multiple;$('multipleLoadPanel').hidden=!multiple;state.selectedProduct=null;showProduct();if(multiple)renderMultipleProducts();else{state.multiSelection.clear();$('multipleProductSearch').value='';updateMultipleFooter()}}
function addMultipleProducts(){if(!state.activeVisit&&!state.editingOrder&&!state.offlineOrderMode)return toast('Comience el pedido y seleccione el cliente.');if(!state.multiSelection.size)return toast('Ingrese cantidad en al menos un artículo.');for(const {product,quantity} of state.multiSelection.values()){const existing=state.cart.find(x=>x.product.organizacion===product.organizacion&&x.product.codigo===product.codigo);if(existing)existing.quantity+=quantity;else state.cart.push({product,quantity})}state.multiSelection.clear();$('multipleProductSearch').value='';renderCart();renderMultipleProducts();toast('Artículos agregados al pedido.')}
