function renderCart(){updateOrderHeaderLock();const body=$('lines');body.innerHTML=state.cart.map((x,i)=>`<tr class="cart-line"><td class="cart-description">${escapeHtml(x.product.descripcion)}</td><td class="cart-quantity"><span class="mobile-label">Cant.</span>${number.format(x.quantity)}</td><td class="cart-price"><span class="mobile-label">Precio</span>${money.format(x.product.precio)}</td><td class="cart-amount">${money.format(x.quantity*x.product.precio)}</td><td class="cart-actions"><div class="line-actions"><button class="edit-line secondary" data-index="${i}" title="Editar artículo" aria-label="Editar artículo">✏️</button><button class="remove" data-index="${i}" title="Eliminar artículo" aria-label="Eliminar artículo">🗑️</button></div></td></tr>`).join('');$('emptyCart').style.display=state.cart.length?'none':'block';$('lineCount').textContent=`${state.cart.length} ${state.cart.length===1?'artículo':'artículos'}`;body.querySelectorAll('.edit-line').forEach(b=>b.onclick=()=>editCartLine(+b.dataset.index));body.querySelectorAll('.remove').forEach(b=>b.onclick=()=>{state.cart.splice(+b.dataset.index,1);renderCart()});renderTotal()}
function editCartLine(index){const line=state.cart[index];if(!line)return;const dialog=$('editLineDialog');$('editLineDescription').value=line.product.descripcion;$('editLineQuantity').value=String(line.quantity);$('editLinePrice').textContent=money.format(line.product.precio);$('editLineCancel').onclick=()=>dialog.close();$('editLineSave').onclick=()=>{const description=$('editLineDescription').value.trim(),quantity=Number($('editLineQuantity').value);if(!description)return toast('Ingrese una descripción.');if(!Number.isFinite(quantity)||quantity<=0)return toast('Ingrese una cantidad válida.');line.product={...line.product,descripcion:description};line.quantity=quantity;dialog.close();renderCart()};dialog.showModal();$('editLineDescription').focus()}
function parseAmount(value){let text=String(value??'').trim().replace(/[^0-9,.-]/g,'');if(!text)return 0;if(text.includes(','))text=text.replaceAll('.','').replace(',','.');else if(/^\d{1,3}(\.\d{3})+$/.test(text))text=text.replaceAll('.','');return Number(text)||0}
function formatBudget(){const value=parseAmount($('budget').value);$('budget').value=value>0?money.format(value):'';renderTotal()}
function renderTotal(){const client=selectedClient(),gross=state.cart.reduce((sum,x)=>sum+x.quantity*x.product.precio,0),net=state.cart.reduce((sum,x)=>sum+(x.quantity*x.product.precio)/(1+(Number(x.product.alic)||0)/100),0),perception=Math.round(net*(Number(client?.alicPercepcion)||0))/100,total=gross+perception;$('total').textContent=money.format(total);$('perceptionNote').textContent=perception>0?`Incluye Perc. IIBB de ${money.format(perception)}`:'';const budget=parseAmount($('budget').value),status=$('budgetStatus');if(!budget){status.textContent='';return}const diff=budget-total;status.textContent=diff>=0?`Disponible: ${money.format(diff)}`:`Excedido: ${money.format(Math.abs(diff))}`;status.className=`budget-status ${diff>=0?'positive':'negative'}`}
